    server = CodexAppServer("codex")
    server._process = SimpleNamespace(pid=4321, returncode=None)
    server.ensure_started = AsyncMock()

    async def request(method, params, **_kwargs):
        if method == "model/list":
            return {
                "data": [{
                    "id": "gpt-5.6-sol",
                    "serviceTiers": [{"id": "priority"}],
                }],
            }
        if method == "thread/start":
            return {
                "thread": {
                    "id": "thread-fast-race",
                    "status": {"type": "idle"},
                },
                "serviceTier": "priority",
            }
        if method == "turn/start":
            server._handle_notification(
                "turn/completed",
                {
                    "threadId": "thread-fast-race",
                    "turn": {
                        "id": "turn-fast-race",
                        "status": "completed",
                        "items": [{
                            "id": "input-fast-race",
                            "type": "userMessage",
                            "clientId": params["clientUserMessageId"],
                        }],
                    },
                },
            )
            return {"turn": {"id": "turn-fast-race"}}
        raise AssertionError(method)

    server._request = AsyncMock(side_effect=request)
    process, thread_id = await server.start_turn(
        prompt="fast",
        cwd="/tmp",
        model="gpt-5.6-sol",
        effort="high",
        resume_session_id=None,
        git_env=None,
        task_id=96,
        codex_service_tier="priority",
    )

    events = []
    while True:
        raw = await process.stdout.readline()
        if not raw:
            break
        events.append(json.loads(raw))

    assert thread_id == "thread-fast-race"
    assert process.returncode == 0
    assert [event["type"] for event in events] == [
        "thread.started",
        "system_event",
        "turn.completed",
    ]
    assert events[1]["admitted_service_tier"] == "priority"
    assert events[1]["turn_id"] == "turn-fast-race"


