@pytest.mark.asyncio
async def test_interrupt_active_goal_descendant_without_visible_turn():
    """A Goal-backed child can be active while thread/read exposes no turn."""

    server = CodexAppServer("codex")
    server._process = SimpleNamespace(pid=4321, returncode=None)
    server.ensure_started = AsyncMock()

    async def request(method, params, **_kwargs):
        if method == "thread/start":
            return {
                "thread": {
                    "id": "thread-root",
                    "status": {"type": "idle"},
                },
            }
        if method == "turn/start":
            return {"turn": {"id": "turn-root"}}
        if method == "thread/read":
            return {
                "thread": {
                    "id": "thread-child",
                    "status": {"type": "active", "activeFlags": []},
                    "turns": [],
                },
            }
        if method == "thread/goal/set":
            assert params == {
                "threadId": "thread-child",
                "status": "paused",
            }
            asyncio.get_running_loop().call_soon(
                server._handle_notification,
                "thread/status/changed",
                {
                    "threadId": "thread-child",
                    "status": {"type": "idle"},
                },
            )
            return {}
        raise AssertionError(f"unexpected request: {method}")

    server._request = AsyncMock(side_effect=request)
    process, _ = await server.start_turn(
        prompt="coordinate a goal-backed child",
        cwd="/tmp",
        model="gpt-5.5",
        effort="low",
        resume_session_id=None,
        git_env=None,
        task_id=140,
    )
    await process.stdout.readline()
    server._handle_notification("item/completed", {
        "threadId": "thread-root",
        "turnId": "turn-root",
        "item": {
            "type": "subAgentActivity",
            "id": "spawn-1",
            "agentThreadId": "thread-child",
            "agentPath": "/root/child",
            "kind": "started",
        },
    })
    server._handle_notification("turn/completed", {
        "threadId": "thread-root",
        "turn": {
            "id": "turn-root",
            "status": "interrupted",
            "error": None,
        },
    })

    assert await asyncio.wait_for(process.wait(), timeout=1) == 130
    assert server._contexts_by_descendant == {}
    assert any(
        call.args[0] == "thread/goal/set"
        for call in server._request.await_args_list
    )


@pytest.mark.asyncio
async def test_descendant_terminal_deadline_holds_adapter_until_proven(
    monkeypatch,
):
    monkeypatch.setattr(
        "backend.services.codex_app_server._DESCENDANT_RECONCILE_INTERVAL",
        0.001,
    )
    monkeypatch.setattr(
        "backend.services.codex_app_server._DESCENDANT_TERMINAL_TIMEOUT",
        0.02,
    )
    server = CodexAppServer("codex")
    server._process = SimpleNamespace(pid=4321, returncode=None)
    server.ensure_started = AsyncMock()

    async def request(method, params, **_kwargs):
        if method == "thread/start":
            return {
                "thread": {
                    "id": "thread-root",
                    "status": {"type": "idle"},
                },
            }
        if method == "turn/start":
            return {"turn": {"id": "turn-root"}}
        if method == "thread/read":
            return {
                "thread": {
                    "id": params["threadId"],
                    "status": {"type": "active", "activeFlags": []},
                },
            }
        if method == "thread/goal/set":
            raise CodexAppServerError("no active goal for thread")
        raise AssertionError(f"unexpected request: {method}")

    server._request = AsyncMock(side_effect=request)
    process, _ = await server.start_turn(
        prompt="work",
        cwd="/tmp",
        model="gpt-5.5",
        effort="low",
        resume_session_id=None,
        git_env=None,
        task_id=15,
    )
    await process.stdout.readline()
    server._handle_notification("item/completed", {
        "threadId": "thread-root",
        "turnId": "turn-root",
        "item": {
            "type": "subAgentActivity",
            "id": "spawn-1",
            "agentThreadId": "thread-child",
            "agentPath": "/root/child",
            "kind": "started",
        },
    })
    server._handle_notification("turn/completed", {
        "threadId": "thread-root",
        "turn": {"id": "turn-root", "status": "completed", "error": None},
    })

    await asyncio.sleep(0.08)
    context = server._contexts_by_thread["thread-root"]
    assert process.returncode is None
    assert (
        context.deferred_terminal_notification["turn"]["status"]
        == "failed"
    )
    assert server._contexts_by_descendant["thread-child"] is context

    # Only an authoritative terminal notification releases EOF.
    server._handle_notification("thread/status/changed", {
        "threadId": "thread-child",
        "status": {"type": "idle"},
    })
    assert await asyncio.wait_for(process.wait(), timeout=1) == 1
    lines = []
    while line := await process.stdout.readline():
        lines.append(json.loads(line))
    assert [line["type"] for line in lines] == ["turn.failed"]
    assert "could not prove all native sub-agents terminal" in (
        lines[0]["error"]["message"]
    )


@pytest.mark.asyncio
async def test_unconfirmed_descendant_abandon_escalates_transport_shutdown(
    tmp_path,
):
    home = normalize_codex_home(tmp_path / "descendant-abandon")
    server = CodexAppServer("codex", codex_home=home)
    server._process = SimpleNamespace(pid=4321, returncode=None)
    server.ensure_started = AsyncMock()

    async def request(method, params, **_kwargs):
        if method == "thread/start":
            return {
                "thread": {
                    "id": "thread-root",
                    "status": {"type": "idle"},
                },
            }
        if method == "turn/start":
            return {"turn": {"id": "turn-root"}}
        if method == "thread/read":
            assert params == {
                "threadId": "thread-child",
                "includeTurns": True,
            }
            return {
                "thread": {
                    "id": "thread-child",
                    "status": {"type": "active", "activeFlags": []},
                    "turns": [],
                },
            }
        raise AssertionError(f"unexpected request: {method}")

    server._request = AsyncMock(side_effect=request)
    server.shutdown = AsyncMock()
    process, _ = await server.start_turn(
        prompt="work",
        cwd="/tmp",
        model="gpt-5.5",
        effort="low",
        resume_session_id=None,
        git_env=None,
        task_id=16,
    )
    await process.stdout.readline()
    server._handle_notification("item/completed", {
        "threadId": "thread-root",
        "turnId": "turn-root",
        "item": {
            "type": "subAgentActivity",
            "id": "spawn-1",
            "agentThreadId": "thread-child",
            "agentPath": "/root/child",
            "kind": "started",
        },
    })
    server._handle_notification("turn/completed", {
        "threadId": "thread-root",
        "turn": {"id": "turn-root", "status": "completed", "error": None},
    })
    await asyncio.sleep(0)

    interrupt_confirmed = await server.abandon_turn(
        process,
        "consumer cancelled",
    )
    assert interrupt_confirmed is False
    assert process.returncode is None
    assert server._contexts_by_thread["thread-root"].process is process
    assert server._contexts_by_turn["turn-root"].process is process
    assert server._contexts_by_descendant["thread-child"].process is process

    registry = CodexAppServerRegistry("codex")
    registry._servers[home] = server
    transport_stopped = await registry.abort_unclaimed_turn(
        home,
        process,
        reason="consumer cancelled",
    )

    assert transport_stopped is True
    server.shutdown.assert_awaited_once()
    assert process.returncode == 130
    assert server._contexts_by_thread == {}
    assert server._contexts_by_turn == {}
    assert home not in registry._servers
    assert home not in registry._draining


@pytest.mark.asyncio
async def test_unconfirmed_unclaimed_abort_does_not_kill_live_peer(tmp_path):
    home = normalize_codex_home(tmp_path / "shared-unclaimed-abort")
    server = CodexAppServer("codex", codex_home=home)
    target = CodexTurnProcess(1001, AsyncMock())
    peer = CodexTurnProcess(1002, AsyncMock())
    server._contexts_by_thread = {
        "thread-target": SimpleNamespace(process=target),
        "thread-peer": SimpleNamespace(process=peer),
    }
    server.abandon_turn = AsyncMock(return_value=False)
    server.shutdown = AsyncMock()
    registry = CodexAppServerRegistry("codex")
    registry._servers[home] = server

    with pytest.raises(
        CodexSharedTransportBusyError,
        match="another live turn shares",
    ):
        await registry.abort_unclaimed_turn(
            home,
            target,
            reason="admission caller cancelled",
        )

    server.shutdown.assert_not_awaited()
    assert target.returncode is None
    assert peer.returncode is None
    assert registry._servers[home] is server
    assert home in registry._draining


@pytest.mark.asyncio
async def test_claimed_stop_refuses_to_disrupt_shared_transport_with_live_peer(
    tmp_path,
):
    """An explicit stop stays effective when exact descendant cleanup wedges."""

    home = normalize_codex_home(tmp_path / "shared-claimed-stop")
