@pytest.mark.asyncio
@pytest.mark.parametrize(
    (
        "will_retry",
        "terminal_status",
        "expected_type",
        "expected_terminal",
        "expected_exit_code",
        "expected_termination_kind",
    ),
    [
        pytest.param(
            True, "completed", "turn.retrying", False, 0, None,
            id="retrying",
        ),
        pytest.param(
            False, "completed", "turn.failed", True, 1, None,
            id="non-retry-fatal",
        ),
        pytest.param(
            False, "interrupted", "turn.failed", True, 1, None,
            id="non-retry-error-beats-interrupt",
        ),
    ],
)
async def test_error_notification_respects_will_retry(
    will_retry,
    terminal_status,
    expected_type,
    expected_terminal,
    expected_exit_code,
    expected_termination_kind,
):
    server = CodexAppServer("codex")
    server._process = SimpleNamespace(pid=4321, returncode=None)
    server.ensure_started = AsyncMock()
    server._request = AsyncMock(side_effect=[
        {"thread": {"id": "thread-1", "status": {"type": "idle"}}},
        {"turn": {"id": "turn-1"}},
    ])
    process, _ = await server.start_turn(
        prompt="continue",
        cwd="/tmp",
        model="gpt-5.6-sol",
        effort="medium",
        resume_session_id=None,
        git_env=None,
        task_id=297,
    )
    await process.stdout.readline()

    error = {
        "message": "Reconnecting... 1/5",
        "codexErrorInfo": {
            "responseStreamDisconnected": {"httpStatusCode": 409},
        },
        "additionalDetails": (
            "unexpected status 409 Conflict: "
            '{"detail":"all logged-in accounts are busy"}'
        ),
    }
    server._handle_notification("error", {
        "threadId": "thread-1",
        "turnId": "turn-1",
        "error": error,
        "willRetry": will_retry,
    })

    notification = json.loads((await process.stdout.readline()).decode())
    assert notification == {
        "type": expected_type,
        "error": error,
        "turn_id": "turn-1",
        "will_retry": will_retry,
        "terminal": expected_terminal,
    }
    assert process.returncode is None

    server._handle_notification("turn/completed", {
        "threadId": "thread-1",
        "turn": {
            "id": "turn-1",
            "status": terminal_status,
            "error": None,
        },
    })

    completed = json.loads((await process.stdout.readline()).decode())
    assert completed["type"] == "turn.completed"
    assert completed["turn_id"] == "turn-1"
    if will_retry:
        assert completed["status"] == "completed"
        assert completed["success"] is True
        assert completed["error"] is None
    else:
        assert completed["status"] == "failed"
        assert completed["success"] is False
        assert completed["error"] == error
    assert await process.wait() == expected_exit_code
    assert process.termination_kind == expected_termination_kind


@pytest.mark.asyncio
async def test_interleaved_notifications_are_isolated_by_turn():
    """Concurrent tasks must never receive another thread's output."""
    server = CodexAppServer("codex")
    server._process = SimpleNamespace(pid=4321, returncode=None)
    server.ensure_started = AsyncMock()
    server._request = AsyncMock(side_effect=[
        {"thread": {"id": "thread-a", "status": {"type": "idle"}}},
        {"turn": {"id": "turn-a"}},
        {"thread": {"id": "thread-b", "status": {"type": "idle"}}},
        {"turn": {"id": "turn-b"}},
    ])
    process_a, _ = await server.start_turn(
        prompt="a", cwd="/tmp", model="gpt-5.5", effort="low",
        resume_session_id=None, git_env=None, task_id=1,
    )
    process_b, _ = await server.start_turn(
        prompt="b", cwd="/tmp", model="gpt-5.5", effort="low",
        resume_session_id=None, git_env=None, task_id=2,
    )
    await process_a.stdout.readline()
    await process_b.stdout.readline()

    # Deliberately deliver B before A, as happens under real concurrent turns.
    for thread, turn, item, text in (
        ("thread-b", "turn-b", "msg-b", "B"),
        ("thread-a", "turn-a", "msg-a", "A"),
    ):
        server._handle_notification("item/agentMessage/delta", {
            "threadId": thread, "turnId": turn, "itemId": item, "delta": text,
        })
        server._handle_notification("item/completed", {
            "threadId": thread, "turnId": turn,
            "item": {"type": "agentMessage", "id": item, "text": text},
        })
        server._handle_notification("turn/completed", {
            "threadId": thread,
            "turn": {"id": turn, "status": "completed", "error": None},
        })

    async def read_all(process):
        rows = []
        while line := await process.stdout.readline():
            rows.append(json.loads(line))
        return rows

    rows_a, rows_b = await asyncio.gather(read_all(process_a), read_all(process_b))
    assert [row.get("delta") for row in rows_a if "delta" in row] == ["A"]
    assert [row.get("delta") for row in rows_b if "delta" in row] == ["B"]
    assert rows_a[1]["item"]["text"] == "A"
    assert rows_b[1]["item"]["text"] == "B"
    assert await process_a.wait() == await process_b.wait() == 0


@pytest.mark.asyncio
async def test_reader_exit_does_not_leak_shared_stderr_to_tasks():
    """A crashed shared process must unblock every waiter instead of hanging."""
    server = CodexAppServer("codex")
    stale_stderr = "historic router error from an unrelated task"
    server._stderr_lines.append(stale_stderr)
    server._process = SimpleNamespace(pid=4321, returncode=None)
    server.ensure_started = AsyncMock()
    server._request = AsyncMock(side_effect=[
        {"thread": {"id": "thread-1", "status": {"type": "idle"}}},
        {"turn": {"id": "turn-1"}},
    ])
    turn_process, _ = await server.start_turn(
        prompt="hi", cwd="/tmp", model="gpt-5.5", effort="low",
        resume_session_id=None, git_env=None, task_id=1,
    )
    await turn_process.stdout.readline()
    context = server._contexts_by_thread["thread-1"]
    server._handle_notification("item/completed", {
        "threadId": "thread-1",
        "turnId": "turn-1",
        "item": {
            "type": "subAgentActivity",
            "id": "spawn-1",
            "agentThreadId": "thread-child",
            "agentPath": "/root/child",
            "kind": "started",
        },
    })
    server._handle_notification("turn/completed", {
        "threadId": "thread-1",
        "turn": {"id": "turn-1", "status": "completed", "error": None},
    })
    await asyncio.sleep(0)
    assert context.descendant_guard_task is not None
    assert turn_process.returncode is None
    pending = asyncio.get_running_loop().create_future()

    stdout = asyncio.StreamReader()
    stdout.feed_eof()
    fake_process = SimpleNamespace(
        stdout=stdout,
        wait=AsyncMock(return_value=1),
    )
    server._pending[99] = (fake_process, pending)
    await server._read_loop(fake_process)

    assert await turn_process.wait() == 1
    assert not server._contexts_by_thread
    assert not server._contexts_by_turn
    assert not server._contexts_by_descendant
    assert context.descendant_guard_task is None
    assert not server._pending
    with pytest.raises(
        CodexAppServerError,
        match=r"exited unexpectedly \(exit code 1\)",
    ) as exc_info:
        await pending
    assert stale_stderr not in str(exc_info.value)
    turn_stderr = (await turn_process.stderr.read()).decode()
    assert "exited unexpectedly (exit code 1)" in turn_stderr
    assert stale_stderr not in turn_stderr


@pytest.mark.asyncio
async def test_reader_exit_zero_during_shutdown_is_not_reported_as_unexpected():
    """A CCM-requested clean exit must not masquerade as a task crash."""

